// Accessible top-down fallback when WebGL is unavailable.
const $=id=>document.getElementById(id);$('loading').remove();$('intro').style.display='none';$('walk').disabled=true;$('walk').textContent='3D unavailable';$('overview').textContent='2D map';$('walking').hidden=false;$('walkStatus').textContent='2D fallback · WebGL unavailable in this browser';
const old=$('world'),c=document.createElement('canvas');c.id='world';c.setAttribute('aria-label','2D campus map');old.replaceWith(c);const ctx=c.getContext('2d');let features=[],zoom=1,offset=[0,0],drag=null,selected=null;
const data=await(await fetch('./campus.json')).json();const config=await(await fetch('./model-config.json')).json();features=[...data.features,...config.extraPonds.map(p=>({...p,tags:{natural:'water'}}))];features.sort((a,b)=>{const rank=f=>f.tags.natural==='wood'?0:f.tags.natural==='water'?1:f.tags.highway?2:f.tags.building?4:3;return rank(a)-rank(b)});const boundary=features.find(f=>f.tags.amenity==='university');
function draw(){c.width=innerWidth*devicePixelRatio;c.height=innerHeight*devicePixelRatio;ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);ctx.fillStyle='#edf1e4';ctx.fillRect(0,0,innerWidth,innerHeight);const scale=Math.min(innerWidth/700,innerHeight/900)*zoom;ctx.translate(innerWidth/2-50+offset[0],innerHeight/2+offset[1]);ctx.scale(scale,scale);function path(p){ctx.beginPath();p.forEach((v,i)=>i?ctx.lineTo(...v):ctx.moveTo(...v))}path(boundary.points);ctx.fillStyle='#d1dfbc';ctx.fill();for(const f of features){if(f.tags.highway){path(f.points);ctx.strokeStyle='#9ca99c';ctx.lineWidth=['footway','steps','path'].includes(f.tags.highway)?2:6;ctx.stroke();}if(f.tags.natural==='wood'){path(f.points);ctx.fillStyle='#6f875d';ctx.fill();}if(f.tags.natural==='water'){path(f.points);ctx.fillStyle='#526e48';ctx.fill();}if(f.tags.sport||f.tags.building){path(f.points);ctx.fillStyle=f.tags.sport?'#a2bd83':'#985344';ctx.fill();ctx.strokeStyle='#edf1e4';ctx.lineWidth=1;ctx.stroke();}const name=f.tags.name&&f.tags.building?f.tags.name:f.tags.amenity==='library'?'Library':f.id==='618490372'?'Student Activity Centre':null;if(name){ctx.font='12px Arial';ctx.fillStyle='#173e38';ctx.fillText(name,f.points[0][0],f.points[0][1]-8)}}if(selected){ctx.beginPath();ctx.arc(...selected,9/scale,0,7);ctx.strokeStyle='#cf743b';ctx.lineWidth=3/scale;ctx.stroke();}}
const places=features.filter(f=>f.tags.building&&(f.tags.name||f.tags.amenity==='library'||f.id==='618490372'));places.forEach((p,i)=>{const o=document.createElement('option');o.value=i;o.textContent=p.tags.name||(p.id==='618490372'?'Student Activity Centre':'Library');$('destination').append(o)});$('destination').onchange=e=>{if(e.target.value==='')return;const p=places[+e.target.value];selected=p.points[0];$('location').textContent=p.tags.name||(p.id==='618490372'?'Student Activity Centre':'Library');draw()};$('map').style.display='none';$('location').textContent='Drag to pan · Scroll to zoom';$('reset').onclick=()=>{zoom=1;offset=[0,0];selected=null;draw()};$('about').onclick=()=>$('info').showModal();$('closeInfo').onclick=()=>$('info').close();c.onpointerdown=e=>{drag=[e.clientX,e.clientY];c.setPointerCapture(e.pointerId)};c.onpointermove=e=>{if(!drag)return;offset[0]+=e.clientX-drag[0];offset[1]+=e.clientY-drag[1];drag=[e.clientX,e.clientY];draw()};c.onpointerup=c.onpointercancel=()=>drag=null;c.onwheel=e=>{e.preventDefault();zoom=Math.max(.5,Math.min(4,zoom*Math.exp(-e.deltaY*.001)));draw()};window.addEventListener('resize',draw);draw();
